sdl:
directive @cost(weight: String!) on ARGUMENT_DEFINITION | ENUM | FIELD_DEFINITION | INPUT_FIELD_DEFINITION | OBJECT | SCALAR
directive @listSize(assumedSize: Int, slicingArguments: [String!], sizedFields: [String!], requireOneSlicingArgument: Boolean = true) on FIELD_DEFINITION

union Result = A | B

type A {
  a: Int @cost(weight: "10")
}

type B {
  b: Int @cost(weight: "20")
}

type Query {
  results(limit: Int!): [Result]
    @cost(weight: "1")
    @listSize(slicingArguments: ["limit"])
}

operation:
query Test($n: Int!) {
  results(limit: $n) {
    ... on A { a }
    ... on B { b }
  }
}
